}

/// Layout the given row with the default row state.
#[inline]
pub(super) fn layout_row(
    &mut self,
    y: usize,
    engine: &mut Engine,
    disambiguator: usize,
) -> SourceResult<()> {
    self.layout_row_with_state(y, engine, disambiguator, RowState::default())?;
