18	/// Layout the list.
19	#[typst_macros::time(span = elem.span())]
20	pub fn layout_list(
21	    elem: &Packed<ListElem>,
22	    engine: &mut Engine,
23	    locator: Locator,
24	    styles: StyleChain,
25	    regions: Regions,
26	) -> SourceResult<Fragment> {
27	    let indent = elem.indent.get(styles);
28	    let body_indent = elem.body_indent.get(styles);
29	    let tight = elem.tight.get(styles);
30	    let gutter = elem.spacing.get(styles).unwrap_or_else(|| {
31	        if tight { styles.get(ParElem::leading) } else { styles.get(ParElem::spacing) }
32	    });
33	    let is_rtl = styles.get(TextElem::dir).resolve(styles) == Dir::RTL;
34	
35	    let Depth(depth) = styles.get(ListElem::depth);
36	
37	    // Use the user's preferred vertical alignment. Among other things, it
38	    // avoids '#set align' interference with the list.
39	    let marker_align = elem.marker_align.get(styles);
40	    let baseline_align = marker_align.y().is_none();
41	    let marker = elem.marker.get_ref(styles);
42	    let marker = marker
43	        .v
44	        .resolve(engine, styles, depth, marker.span)
45	        .trace(engine.world, Tracepoint::process::<ListElem>, elem.span())?
46	        .aligned(marker_align);
47	
48	    let mut items = vec![];
49	    for item in &elem.children {
50	        // Text in wide lists shall always turn into paragraphs.
51	        let mut body = item.body.clone();
52	        if !tight {
53	            body += ParbreakElem::shared();
54	        }
55	        let body = body.set(ListElem::depth, Depth(1));
56	
57	        let item = ItemContent {
58	            marker: PdfMarkerTag::ListItemLabel(marker.clone()),
59	            body: PdfMarkerTag::ListItemBody(body),
60	        };
61	
62	        items.push(item);
63	    }
64	
65	    let layouter = ListLayouter::new(
66	        gutter,
67	        elem.span(),
68	        indent,
69	        body_indent,
70	        baseline_align,
71	        is_rtl,
72	        styles,
73	    );
74	
75	    layout_items(layouter, items, engine, locator, styles, regions)
76	}
