78	/// Layout the enumeration.
79	#[typst_macros::time(span = elem.span())]
80	pub fn layout_enum(
81	    elem: &Packed<EnumElem>,
82	    engine: &mut Engine,
83	    locator: Locator,
84	    styles: StyleChain,
85	    regions: Regions,
86	) -> SourceResult<Fragment> {
87	    let numbering = elem.numbering.get_ref(styles);
88	    let reversed = elem.reversed.get(styles);
89	    let indent = elem.indent.get(styles);
90	    let body_indent = elem.body_indent.get(styles);
91	    let tight = elem.tight.get(styles);
92	    let gutter = elem.spacing.get(styles).unwrap_or_else(|| {
93	        if tight { styles.get(ParElem::leading) } else { styles.get(ParElem::spacing) }
94	    });
95	    let is_rtl = styles.get(TextElem::dir).resolve(styles) == Dir::RTL;
96	
97	    let mut items = vec![];
98	    let mut number = elem
99	        .start
100	        .get(styles)
101	        .unwrap_or_else(|| if reversed { elem.children.len() as u64 } else { 1 });
102	    let mut parents = styles.get_cloned(EnumElem::parents);
103	
104	    let full = elem.full.get(styles);
105	
106	    // Horizontally align based on the given respective parameter.
107	    // Vertically align to the top to avoid inheriting `horizon` or `bottom`
108	    // alignment from the context and having the number be displaced in
109	    // relation to the item it refers to.
110	    let number_align = elem.number_align.get(styles);
111	    let baseline_align = number_align.y().is_none();
112	
113	    for item in &elem.children {
114	        number = item.number.get(styles).unwrap_or(number);
115	
116	        let context = Context::new(None, Some(styles));
117	        let resolved = if full {
118	            parents.push(number);
119	            let content = numbering
120	                .apply(engine, context.track(), item.span(), &parents)?
121	                .display();
122	            parents.pop();
123	            content
124	        } else {
125	            match numbering {
126	                Numbering::Pattern(pattern) => TextElem::packed(pattern.apply_kth(
127	                    engine,
128	                    item.span(),
129	                    parents.len(),
130	                    number,
131	                )),
132	                Numbering::Func(_) => numbering
133	                    .apply(engine, context.track(), item.span(), &[number])?
134	                    .display(),
135	            }
136	        };
137	
138	        // Disable overhang as a workaround to end-aligned dots glitching
139	        // and decreasing spacing between numbers and items.
140	        let resolved = resolved.aligned(number_align).set(TextElem::overhang, false);
141	
142	        // Text in wide enums shall always turn into paragraphs.
143	        let mut body = item.body.clone();
144	        if !tight {
145	            body += ParbreakElem::shared();
146	        }
147	
148	        let body = body.set(EnumElem::parents, smallvec![number]);
149	
150	        let item = ItemContent {
151	            marker: PdfMarkerTag::ListItemLabel(resolved),
152	            body: PdfMarkerTag::ListItemBody(body),
153	        };
154	
155	        items.push(item);
156	        number =
157	            if reversed { number.saturating_sub(1) } else { number.saturating_add(1) };
158	    }
159	
160	    let layouter = ListLayouter::new(
161	        gutter,
162	        elem.span(),
163	        indent,
164	        body_indent,
165	        baseline_align,
166	        is_rtl,
167	        styles,
168	    );
169	
170	    layout_items(layouter, items, engine, locator, styles, regions)
171	}
