173	/// Structure with the content for each list item.
174	struct ItemContent {
175	    /// The item marker.
176	    marker: Content,
177	    /// The item body.
178	    body: Content,
179	}
180	
181	/// Layout data shared across all list items.
182	struct ListLayouter {
183	    /// Gutter spacing between items.
184	    gutter: Length,
185	    /// Span of the list/enum element.
186	    span: Span,
187	    /// List indent from the text start.
188	    indent: Abs,
189	    /// Indent between the marker and the body.
190	    body_indent: Abs,
191	    /// Whether baseline alignment should be enabled. When disabled, markers
192	    /// control their own alignment.
193	    baseline_align: bool,
194	    /// Whether RTL was the chosen text direction.
195	    is_rtl: bool,
196	    /// Maximum measured width of a marker, so they may align horizontally
197	    /// relative to each other.
198	    marker_width: Abs,
199	    /// If the list may not expand to fill the whole region (e.g. if `width:
200	    /// auto` was used), then this holds the measured width of an item body, so
201	    /// they may align horizontally relative to each other.
202	    body_width: Option<Abs>,
203	}
204	
205	impl ListLayouter {
206	    /// Create a new list layouter with defaults for values that will be
207	    /// calculated later.
208	    fn new(
209	        gutter: Length,
210	        span: Span,
211	        indent: Length,
212	        body_indent: Length,
213	        baseline_align: bool,
214	        is_rtl: bool,
215	        styles: StyleChain,
216	    ) -> Self {
217	        let indent = indent.resolve(styles);
218	        let body_indent = body_indent.resolve(styles);
219	
220	        Self {
221	            gutter,
222	            span,
223	            indent,
224	            body_indent,
225	            baseline_align,
226	            is_rtl,
227	
228	            // These will be calculated later.
229	            marker_width: Abs::zero(),
230	            body_width: None,
231	        }
232	    }
233	}
234	
235	/// Layout list items.
236	///
237	/// This is done in 4 steps:
238	///
239	/// 1. Compute marker widths for horizontal marker alignment;
240	/// 2. If necessary (when within a `width: auto` block or page), compute body
241	///    widths as well for horizontal body alignment to work;
242	/// 3. Generate list item layouters, each of which is responsible for vertical
243	///    marker alignment (baseline-aligned or not, depending on user settings);
244	/// 4. Pass each list item to the stack layouter. The stack layouter makes it
245	///    possible for them to expand to the full available width, allowing for center
246	///    or right alignment to work within the item body.
247	#[typst_macros::time(span = layouter.span)]
248	fn layout_items(
249	    mut layouter: ListLayouter,
250	    items: Vec<ItemContent>,
251	    engine: &mut Engine,
252	    locator: Locator,
253	    styles: StyleChain,
254	    regions: Regions,
255	) -> SourceResult<Fragment> {
256	    // Store locators used during measuring to ensure the same locators will be
257	    // used later when laying out. This is needed to make introspection work
258	    // properly.
259	    let mut locator = locator.split();
260	    let locators: Vec<_> = items
261	        .iter()
262	        .map(|item| {
263	            let marker_locator = locator.next(&item.marker.span());
264	            let body_locator = locator.next(&item.body.span());
265	            (marker_locator, body_locator)
266	        })
267	        .collect();
268	
269	    layouter.marker_width =
270	        measure_markers(&layouter, &items, &locators, engine, styles, regions)?;
271	
272	    if regions.size.x.to_raw().is_infinite() || !regions.expand.x {
273	        layouter.body_width =
274	            Some(measure_bodies(&layouter, &items, &locators, engine, styles, regions)?);
275	    }
276	
277	    let cells =
278	        items
279	            .iter()
280	            .zip(&locators)
281	            .map(|(item, (marker_locator, body_locator))| {
282	                StackLayoutChild::CustomLayouter(|engine, styles, regions| {
283	                    layout_item(
284	                        item,
285	                        &layouter,
286	                        engine,
287	                        marker_locator,
288	                        body_locator,
289	                        styles,
290	                        regions,
291	                    )
292	                })
293	            });
294	
295	    layout_stack_internal(
296	        cells,
297	        layouter.span,
298	        Some(layouter.gutter.into()),
299	        Dir::TTB,
300	        engine,
301	        // This locator should not be used by cells.
302	        locator.next(&()),
303	        styles,
304	        regions,
305	    )
306	}
307	
308	/// Measure marker.
309	fn measure_markers<'a>(
310	    list: &ListLayouter,
311	    items: &[ItemContent],
312	    locators: &[(Locator<'a>, Locator<'a>)],
313	    engine: &mut Engine,
314	    styles: StyleChain,
315	    regions: Regions,
316	) -> SourceResult<Abs> {
317	    let available_width = regions.size.x - list.indent - list.body_indent;
318	
319	    // Measure markers, so we can align them horizontally relative to the
320	    // largest width.
321	    let mut marker_width = Abs::zero();
322	    for (item, (marker_locator, _)) in items.iter().zip(locators) {
323	        let marker = crate::layout_frame(
324	            engine,
325	            &item.marker,
326	            marker_locator.relayout(),
327	            styles,
328	            Region::new(Axes::new(available_width, Abs::inf()), Axes::splat(false)),
329	        )?;
330	        marker_width.set_max(marker.width());
331	    }
332	
333	    // Redistribute width if necessary. It is okay to do this before measuring
334	    // the body (thus effectively checking for the width in two places) since a
335	    // non-zero-width body would cause an overlarge marker to surpass page width
336	    // regardless. That is, this check doesn't affect the semantics of the other
337	    // check, but it is necessary in case we don't measure the body at all.
338	    Ok(marker_width.min(available_width))
339	}
340	
341	/// Infinite space or `width: auto` used. Both would prevent the list from
342	/// expanding to fit, breaking alignment. Therefore, restrict the list size to
343	/// the size of the largest item, prompting list items to align between
344	/// themselves instead of relative to the full page width.
345	fn measure_bodies(
346	    list: &ListLayouter,
347	    items: &[ItemContent],
348	    locators: &[(Locator, Locator)],
349	    engine: &mut Engine,
350	    styles: StyleChain,
351	    regions: Regions,
352	) -> SourceResult<Abs> {
353	    let available_width = regions.size.x - list.indent - list.body_indent;
354	    let mut measured_body_width = Abs::zero();
355	    for (item, (_, body_locator)) in items.iter().zip(locators) {
356	        let body = crate::layout_frame(
357	            engine,
358	            &item.body,
359	            body_locator.relayout(),
360	            styles,
361	            Region::new(Axes::new(available_width, Abs::inf()), Axes::splat(false)),
362	        )?;
363	        measured_body_width.set_max(body.width());
364	    }
365	
366	    // If marker and body together exceed the page width, the marker gets the
367	    // space it requested and the body the rest. This makes some sense since the
368	    // marker comes first, is unlikely to be large, and is unlikely to be able
369	    // to wrap. It also keeps consistency between the case where we measure the
370	    // body and the case where we don't.
371	    Ok(measured_body_width.min(available_width - list.marker_width))
372	}
373	
374	/// Layout the item, with support for vertical marker alignment.
375	#[typst_macros::time(span = item.body.span())]
376	fn layout_item(
377	    item: &ItemContent,
378	    list: &ListLayouter,
379	    engine: &mut Engine,
380	    marker_locator: &Locator,
381	    body_locator: &Locator,
382	    styles: StyleChain,
383	    regions: Regions,
384	) -> SourceResult<Fragment> {
385	    let mut layouter =
386	        ItemLayouter::new(item, list, marker_locator, body_locator, styles, regions);
387	
388	    let mut marker = layouter.layout_marker(
389	        Region::new(
390	            Axes::new(list.marker_width, regions.base().y),
391	            Axes::new(true, false),
392	        ),
393	        engine,
394	    )?;
395	
396	    let mut body = layouter.layout_body(layouter.body_regions, engine)?;
397	
398	    if layouter.list.baseline_align {
399	        layouter.baseline_align(&marker, &mut body, engine)?;
400	    } else {
401	        layouter.vertical_align(&mut marker, &body, engine)?;
402	    }
403	
404	    layouter.finish(marker, body)
405	}
406	
407	/// Layout data for a specific item.
408	///
409	/// Its methods assume only `layout_marker` and `layout_body` are used to layout
410	/// the item's contents.
411	struct ItemLayouter<'a> {
412	    /// Item content to layout.
413	    item: &'a ItemContent,
414	    /// List-wide layout data.
415	    list: &'a ListLayouter,
416	    /// Locator used to measure and layout the marker (must be the same to avoid
417	    /// introspection bugs).
418	    marker_locator: &'a Locator<'a>,
419	    /// Locator used to measure and layout the body (must be the same to avoid
420	    /// introspection bugs).
421	    body_locator: &'a Locator<'a>,
422	    /// Stylechain at this item's location.
423	    styles: StyleChain<'a>,
424	    /// The first body's non-empty frame.
425	    first_frame: usize,
426	    /// The item's regions, but adapted for the body's expected width.
427	    body_regions: Regions<'a>,
428	    /// Total body indent from the left of the region, as well as its offset
429	    /// from the top of the region.
430	    ///
431	    /// Vertical offset is always zero without baseline alignment.
432	    body_offset: Point,
433	    /// Resolved marker indent from the left of the region, as well as its
434	    /// offset from the top of the region.
435	    ///
436	    /// Vertical offset is always zero without baseline alignment.
437	    marker_offset: Point,
438	}
439	
440	impl<'a> ItemLayouter<'a> {
441	    /// Begin item layout by resolving default values of attributes.
442	    fn new(
443	        item: &'a ItemContent,
444	        list: &'a ListLayouter,
445	        marker_locator: &'a Locator<'a>,
446	        body_locator: &'a Locator<'a>,
447	        styles: StyleChain<'a>,
448	        regions: Regions<'a>,
449	    ) -> Self {
450	        let total_body_indent = list.indent + list.marker_width + list.body_indent;
451	
452	        // Restrict the body to the available space.
453	        let mut body_regions = regions;
454	        if let Some(body_width) = list.body_width {
455	            body_regions.size.x = body_width;
456	            body_regions.expand.x = true;
457	        } else {
458	            body_regions.size.x -= total_body_indent;
459	        }
460	
461	        Self {
462	            item,
463	            list,
464	            marker_locator,
465	            body_locator,
466	            styles,
467	            first_frame: 0,
468	            body_regions,
469	            body_offset: Point::with_x(total_body_indent),
470	            marker_offset: Point::with_x(list.indent),
471	        }
472	    }
473	
474	    /// Layout the list marker with the given region data.
475	    fn layout_marker(&self, region: Region, engine: &mut Engine) -> SourceResult<Frame> {
476	        crate::layout_frame(
477	            engine,
478	            &self.item.marker,
479	            self.marker_locator.relayout(),
480	            self.styles,
481	            region,
482	        )
483	    }
484	
485	    /// Layout the list body with the given region data.
486	    fn layout_body(
487	        &mut self,
488	        regions: Regions,
489	        engine: &mut Engine,
490	    ) -> SourceResult<Fragment> {
491	        let fragment = crate::layout_fragment(
492	            engine,
493	            &self.item.body,
494	            self.body_locator.relayout(),
495	            self.styles,
496	            regions,
497	        )?;
498	
499	        // Update the first non-empty frame (ignoring a frame with only tags due
500	        // to a forced region break). If the first frame is not virtually empty,
501	        // then keep the default of 0.
502	        if should_skip_first_frame(&fragment) {
503	            self.first_frame = 1;
504	        }
505	
506	        Ok(fragment)
507	    }
508	
509	    /// Ensure baselines are aligned by either increasing the marker's offset,
510	    /// if the marker is above the body and should thus be moved down, or by both
511	    /// increasing the body's offset and relayouting it with less space, if the
512	    /// body is above the marker.
513	    fn baseline_align(
514	        &mut self,
515	        marker: &Frame,
516	        body_fragment: &mut Fragment,
517	        engine: &mut Engine,
518	    ) -> SourceResult<()> {
519	        // Difference between marker and body baselines, for alignment. A
520	        // positive 'diff' means that the marker is above and must move down,
521	        // whereas a negative 'diff' means that the marker is below, so the body
522	        // must be moved down instead.
523	        let diff = if marker.has_baseline()
524	            && let Some(first) = body_fragment.as_slice().get(self.first_frame)
525	            && first.has_baseline()
526	        {
527	            first.baseline() - marker.baseline()
528	        } else {
529	            // One of the frames has no natural baseline, so baseline alignment
530	            // is disabled.
531	            Abs::zero()
532	        };
533	
534	        if diff >= Abs::zero() {
535	            // Marker's baseline is above the body's baseline, so we can align
536	            // them by moving the baseline downwards, without moving the body.
537	            self.marker_offset.y = diff;
538	        } else {
539	            // Marker's baseline is below the body's baseline, so move the body
540	            // down to avoid overflowing the marker into something above the
541	            // list (item).
542	            //
543	            // To do this, we layout the body again but with '-diff' less space
544	            // (that is, '+diff' more space, as it is negative), and then move
545	            // the result '-diff' units downwards. Of course, this could
546	            // theoretically generate a new result that is even worse - but
547	            // there is only so much we can do with a finite number of
548	            // iterations.
549	            let mut regions = self.body_regions;
550	            regions.size.y += diff;
551	            *body_fragment = self.layout_body(regions, engine)?;
552	
553	            self.body_offset.y = -diff;
554	        }
555	
556	        Ok(())
557	    }
558	
559	    /// Called when explicit marker alignment was specified. Re-layout the
560	    /// marker with the same height as the body's first frame so it may align
561	    /// itself vertically with the body.
562	    fn vertical_align(
563	        &mut self,
564	        marker: &mut Frame,
565	        body: &Fragment,
566	        engine: &mut Engine,
567	    ) -> SourceResult<()> {
568	        // 'Measuring' the height of an 'auto row'.
569	        let height = if let Some(body_first) = body.as_slice().get(self.first_frame) {
570	            // Don't align if the body is too short.
571	            body_first.height().max(marker.height())
572	        } else {
573	            // Body appears to be fully empty, so the marker should not align.
574	            marker.height()
575	        };
576	
577	        let region =
578	            Region::new(Axes::new(self.list.marker_width, height), Axes::splat(true));
579	
580	        *marker = self.layout_marker(region, engine)?;
581	        Ok(())
582	    }
583	
584	    /// Finish list item layout by indenting the body's frames and add the
585	    /// marker to the first non-empty frame.
586	    fn finish(&self, marker: Frame, body_fragment: Fragment) -> SourceResult<Fragment> {
587	        // Collect the item's frames. Here, we add the marker to the first
588	        // non-empty frame, and additionally indent the whole body so it appears
589	        // after the marker.
590	        let mut frames = vec![];
591	        for (i, body_frame) in body_fragment.into_iter().enumerate() {
592	            let width = self.body_offset.x + body_frame.width();
593	
594	            let mut height = body_frame.height() + self.body_offset.y;
595	            if i == self.first_frame {
596	                // Also consider the marker height, but only for the frame into
597	                // which it will be placed.
598	                height.set_max(marker.height() + self.marker_offset.y);
599	            }
600	
601	            let mut frame = Frame::soft(Size::new(width, height));
602	
603	            let mut body_pos = self.body_offset;
604	            if self.list.is_rtl {
605	                // In RTL, items expand to the left, thus the position must
606	                // additionally be offset by the full width. However, since the
607	                // body is always at the end, it will expand to the right in
608	                // LTR, and therefore to the left in RTL. That is, its leftmost
609	                // corner must be at the left of the frame, since it now expands
610	                // to the left.
611	                //
612	                // Or, mathematically:
613	                // body_pos.x = width - (body_frame.width() + body_pos.x)
614	                //            = self.body_offset.x + body_frame.width() -
615	                //                  - (body_frame.width() + self.body_offset.x)
616	                //            = 0.
617	                body_pos.x = Abs::zero();
618	            }
619	
620	            // Only place the marker on the first non-empty frame.
621	            if i == self.first_frame {
622	                let mut marker_pos = self.marker_offset;
623	                if self.list.is_rtl {
624	                    marker_pos.x = width - (self.list.marker_width + marker_pos.x);
625	                }
626	                frame.push_frame(marker_pos, marker.clone());
627	            }
628	
629	            frame.push_frame(body_pos, body_frame);
630	            frames.push(frame);
631	        }
632	
633	        Ok(Fragment::frames(frames))
634	    }
635	}
636	
637	/// Check whether the first frame is essentially empty (only contains tags).
638	/// This usually indicates a forced region break, which we should ignore.
639	fn should_skip_first_frame(fragment: &Fragment) -> bool {
640	    fragment.len() > 1
641	        && is_empty_frame(&fragment.as_slice()[0])
642	        && fragment.iter().skip(1).any(|f| !is_empty_frame(f))
643	}
644	
645	/// Check if a frame is empty (taken from grid layouting).
646	///
647	/// HACK: Also consider frames empty if they only contain tags. Table
648	/// and grid cells need to be locatable for pdf accessibility, but
649	/// the introspection tags interfere with the layouting.
650	fn is_empty_frame(frame: &Frame) -> bool {
651	    frame.items().all(|(_, item)| matches!(item, FrameItem::Tag(_)))
652	}
