12	/// Lays out a [`FractionItem`].
13	#[typst_macros::time(name = "math fraction layout", span = props.span)]
14	pub fn layout_fraction(
15	    item: &FractionItem,
16	    ctx: &mut MathContext,
17	    styles: StyleChain,
18	    props: &MathProperties,
19	) -> SourceResult<()> {
20	    let num = ctx.layout_into_fragment(&item.numerator, styles)?.into_frame();
21	    let denom = ctx.layout_into_fragment(&item.denominator, styles)?.into_frame();
22	
23	    let constants = ctx.font().math();
24	    let size = styles.resolve(TextElem::size);
25	    let math_size = props.size;
26	
27	    let frame = if item.line {
28	        let axis = constants.axis_height.at(size);
29	        let thickness = constants.fraction_rule_thickness.at(size);
30	        let shift_up = match math_size {
31	            MathSize::Display => constants.fraction_numerator_display_style_shift_up,
32	            _ => constants.fraction_numerator_shift_up,
33	        }
34	        .at(size);
35	        let shift_down = match math_size {
36	            MathSize::Display => constants.fraction_denominator_display_style_shift_down,
37	            _ => constants.fraction_denominator_shift_down,
38	        }
39	        .at(size);
40	        let num_min = match math_size {
41	            MathSize::Display => constants.fraction_num_display_style_gap_min,
42	            _ => constants.fraction_numerator_gap_min,
43	        }
44	        .at(size);
45	        let denom_min = match math_size {
46	            MathSize::Display => constants.fraction_denom_display_style_gap_min,
47	            _ => constants.fraction_denominator_gap_min,
48	        }
49	        .at(size);
50	
51	        let num_gap = (shift_up - (axis + thickness / 2.0) - num.descent()).max(num_min);
52	        let denom_gap =
53	            (shift_down + (axis - thickness / 2.0) - denom.ascent()).max(denom_min);
54	
55	        let line_width = num.width().max(denom.width());
56	        let width = line_width + 2.0 * item.padding.at(size);
57	        let height = num.height() + num_gap + thickness + denom_gap + denom.height();
58	        let size = Size::new(width, height);
59	        let num_pos = Point::with_x((width - num.width()) / 2.0);
60	        let line_pos = Point::new(
61	            (width - line_width) / 2.0,
62	            num.height() + num_gap + thickness / 2.0,
63	        );
64	        let denom_pos =
65	            Point::new((width - denom.width()) / 2.0, height - denom.height());
66	        let baseline = line_pos.y + axis;
67	
68	        let mut frame = Frame::soft(size);
69	        frame.set_baseline(baseline);
70	        frame.push_frame(num_pos, num);
71	        frame.push_frame(denom_pos, denom);
72	
73	        let text_fill = styles.get_ref(TextElem::fill).as_decoration();
74	        let line = match styles.get_ref(TextElem::stroke) {
75	            Some(stroke) => Geometry::Rect(Size::new(line_width, thickness))
76	                .filled_and_stroked(
77	                    text_fill.clone(),
78	                    stroke.clone().resolve(styles).unwrap_or_default(),
79	                ),
80	            None => Geometry::Line(Point::with_x(line_width))
81	                .stroked(FixedStroke::from_pair(text_fill, thickness)),
82	        };
83	        frame.push(line_pos, FrameItem::Shape(line, props.span));
84	        frame
85	    } else {
86	        let shift_up = match math_size {
87	            MathSize::Display => constants.stack_top_display_style_shift_up,
88	            _ => constants.stack_top_shift_up,
89	        }
90	        .at(size);
91	        let shift_down = match math_size {
92	            MathSize::Display => constants.stack_bottom_display_style_shift_down,
93	            _ => constants.stack_bottom_shift_down,
94	        }
95	        .at(size);
96	        let gap_min = match math_size {
97	            MathSize::Display => constants.stack_display_style_gap_min,
98	            _ => constants.stack_gap_min,
99	        }
100	        .at(size);
101	
102	        let gap = (shift_up - num.descent()) + (shift_down - denom.ascent());
103	
104	        let width = num.width().max(denom.width()) + 2.0 * item.padding.at(size);
105	        let height = num.height() + gap.max(gap_min) + denom.height();
106	        let size = Size::new(width, height);
107	
108	        let num_pos = Point::with_x((width - num.width()) / 2.0);
109	        let denom_pos =
110	            Point::new((width - denom.width()) / 2.0, height - denom.height());
111	
112	        let baseline = num.ascent() + shift_up + (gap_min - gap).max(Abs::zero()) / 2.0;
113	        let mut frame = Frame::soft(size);
114	        frame.set_baseline(baseline);
115	        frame.push_frame(num_pos, num);
116	        frame.push_frame(denom_pos, denom);
117	        frame
118	    };
119	
120	    ctx.push(FrameFragment::new(props, styles, frame));
121	    Ok(())
122	}
123	
124	/// Lay out a skewed fraction.
125	#[typst_macros::time(name = "math skewed fraction layout", span = props.span)]
126	pub fn layout_skewed_fraction(
127	    item: &SkewedFractionItem,
128	    ctx: &mut MathContext,
129	    styles: StyleChain,
130	    props: &MathProperties,
131	) -> SourceResult<()> {
132	    // Font-derived constants
133	    let constants = ctx.font().math();
134	    let size = styles.resolve(TextElem::size);
135	    let vgap = constants.skewed_fraction_vertical_gap.at(size);
136	    let hgap = constants.skewed_fraction_horizontal_gap.at(size);
137	    let axis = constants.axis_height.at(size);
138	
139	    let num_frame = ctx.layout_into_fragment(&item.numerator, styles)?.into_frame();
140	    let num_size = num_frame.size();
141	    let denom_frame = ctx.layout_into_fragment(&item.denominator, styles)?.into_frame();
142	    let denom_size = denom_frame.size();
143	
144	    // Height of the fraction frame
145	    // We recalculate this value below if the slash glyph overflows
146	    let mut fraction_height = num_size.y + denom_size.y + vgap;
147	
148	    // Build the slash glyph to calculate its size
149	    item.slash.set_stretch_relative_to(fraction_height, Axis::Y);
150	    let slash_frag = ctx.layout_into_fragment(&item.slash, styles)?;
151	    let slash_frame = slash_frag.into_frame();
152	
153	    // Adjust the fraction height if the slash overflows
154	    let slash_size = slash_frame.size();
155	    let vertical_offset = Abs::zero().max(slash_size.y - fraction_height) / 2.0;
156	    fraction_height.set_max(slash_size.y);
157	
158	    // Reference points for all three objects, used to place them in the frame.
159	    let mut slash_up_left = Point::new(num_size.x + hgap / 2.0, fraction_height / 2.0)
160	        - slash_size.to_point() / 2.0;
161	    let mut num_up_left = Point::with_y(vertical_offset);
162	    let mut denom_up_left = num_up_left + num_size.to_point() + Point::new(hgap, vgap);
163	
164	    // Fraction width
165	    let fraction_width = (denom_up_left.x + denom_size.x)
166	        .max(slash_up_left.x + slash_size.x)
167	        + Abs::zero().max(-slash_up_left.x);
168	    // We have to shift everything right to avoid going in the negatives for
169	    // the x coordinate
170	    let horizontal_offset = Point::with_x(Abs::zero().max(-slash_up_left.x));
171	    slash_up_left += horizontal_offset;
172	    num_up_left += horizontal_offset;
173	    denom_up_left += horizontal_offset;
174	
175	    // Build the final frame
176	    let mut fraction_frame = Frame::soft(Size::new(fraction_width, fraction_height));
177	
178	    // Baseline (use axis height to center slash on the axis)
179	    fraction_frame.set_baseline(fraction_height / 2.0 + axis);
180	
181	    // Numerator, Denominator, Slash
182	    fraction_frame.push_frame(num_up_left, num_frame);
183	    fraction_frame.push_frame(denom_up_left, denom_frame);
184	    fraction_frame.push_frame(slash_up_left, slash_frame);
185	
186	    ctx.push(FrameFragment::new(props, styles, fraction_frame));
187	    Ok(())
188	}
